{
  "query": "select * from marts.dim_store where store_code='NW001'"
}

{
  "query": "select count(*), sum(on_hand_qty_base), sum(case when days_to_expiry>=0 then on_hand_qty_base end), min(snapshot_date), max(snapshot_date) from marts.fct_inventory_batch where store_code='NW001'"
}

{
  "query": "select sum(qty_base), min(business_date), max(business_date), count(distinct business_date) from marts.fct_sales where store_code='NW001'"
}

{
  "query": "select sum(qty_base)/30.0 d30, (select sum(qty_base)/184.0 from marts.fct_sales where store_code='NW001') d184 from marts.fct_sales where store_code='NW001' and business_date between date '2026-08-16' and date '2026-09-14'"
}

{
  "value": 26.11,
  "replacement_metric": null,
  "caveats": [
    "On-hand still includes stock reserved for transfers in transit and expired stock that waits for the monthly write-off."
  ],
  "explanation": "NW001 is a store. Its on-hand stock at the 2026-09-15 snapshot is 40,602 base units, and none of it is past expiry. Average sales over the last 30 days (2026-08-16 to 2026-09-14) are about 1,554.9 base units a day, so 40,602 / 1,554.9 \u2248 26.1 days. Using the full 184-day average (about 1,508 a day) gives about 26.9 days."
}
